<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Reset password — Crea-Biz</title><script src="/theme.js"></script><link rel="stylesheet" href="/platform.css"></head><body><main><h1>Reset password</h1><form id="reset-password"><input type="hidden" name="token" value="{{ $token }}"><label>Email<input name="email" type="email" value="{{ request('email') }}" autocomplete="email" required></label><label>New password<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><label>Confirm password<input name="password_confirmation" type="password" autocomplete="new-password" required></label><button>Reset password</button></form><p id="status" role="status"></p><a href="/">Return to sign in</a></main><script src="/account.js" defer></script></body></html>